-- SafetyTraining v20.037
-- Preposto 12h: didactic v2 aligned to ASR 17/04/2025, preserving course version 1.
-- Creates eight role-specific Learning Units and course version 2 in draft.
-- The 4x180-minute allocation is internal didactic design, not a statutory per-module duration.
-- Test Builder/question-bank configuration is intentionally unchanged.

do $do$
declare
  r record;
  v_lu_id uuid;
  v_course_id uuid;
  v_course_version_id uuid;
  v_module_id uuid;
begin
  for r in select * from (values
    ('preposto:ruolo-obblighi-relazioni','PR01 · Ruolo, obblighi e posizione del preposto',90,'Riconoscere il ruolo del preposto, i suoi obblighi e le relazioni con le altre figure della prevenzione.',jsonb_build_object('didactic_version','preposto-v2','code','PR01','minutes',90,'slide_title','Essere preposto: vedere, decidere, intervenire','summary','Il preposto sovraintende all’attività lavorativa e rende operative le direttive ricevute: il suo ruolo si riconosce soprattutto da ciò che controlla e da come interviene quando le condizioni non sono quelle previste.','detail','La lezione distingue nomina, esercizio effettivo del ruolo e relazioni con datore di lavoro, dirigente, lavoratori, RSPP e RLS. Il focus non è memorizzare organigrammi, ma capire quali decisioni e segnalazioni competono al preposto nel lavoro reale.','question','In quale momento una persona smette di essere solo un lavoratore esperto e sta esercitando di fatto funzioni di preposto?','case','Durante un turno un caposquadra distribuisce i compiti, corregge le modalità operative e decide chi può proseguire una lavorazione. Dice però di non essere preposto perché non ha firmato nulla. Come analizzi la situazione?','teacher_expansion',jsonb_build_array('[0–15 min] Parti da tre figure reali e chiedi chi sovraintende concretamente al lavoro.','[15–35 min] Ruolo, obblighi e rapporto con datore, dirigente e lavoratori.','[35–55 min] Preposto di fatto: concentrarsi sulle funzioni esercitate, senza trasformare la lezione in consulenza sul singolo caso aziendale.','[55–75 min] Caso caposquadra: quali comportamenti mostrano l’esercizio del ruolo?','[75–90 min] Mappa personale: chi decide, chi vigila, chi segnala e a chi.'),'common_errors',jsonb_build_array('Ridurre il ruolo alla sola nomina formale.','Presentare il preposto come mini-datore di lavoro.','Confondere vigilanza operativa con attività tecnica propria dell’RSPP.'),'operational',jsonb_build_object('objective','Riconoscere il perimetro operativo del preposto e attivare il corretto flusso di decisione e segnalazione.','step_by_step',jsonb_build_array('Osserva chi dirige operativamente','Identifica direttive e misure da attuare','Vigila sull’esecuzione','Intervieni sulle deviazioni','Segnala ciò che richiede decisioni superiori'),'stop_conditions',jsonb_build_array('Ruolo non chiaro durante attività critica','Direttive incompatibili con condizioni reali','Misura necessaria non disponibile')),'idea_images',jsonb_build_array(jsonb_build_object('file','organigramma-sicurezza.svg','caption','Il preposto dentro il sistema aziendale della prevenzione.'),jsonb_build_object('file','idea-safety-system.svg','caption','Ruoli e flussi: chi decide, chi vigila, chi supporta.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:rapporti-cooperazione','PR02 · Relazioni, cooperazione e flussi di sicurezza',90,'Gestire correttamente i rapporti con datore, dirigente, lavoratori e soggetti della prevenzione.',jsonb_build_object('didactic_version','preposto-v2','code','PR02','minutes',90,'slide_title','Dal problema all’azione: con chi deve cooperare il preposto','summary','Vigilare non basta se l’anomalia non entra nel flusso organizzativo giusto. Il preposto deve saper informare, segnalare e cooperare con chi può rimuovere la causa o modificare l’organizzazione.','detail','Questa unità lavora sulla qualità della segnalazione: fatto osservato, rischio, misura temporanea, destinatario, urgenza, presa in carico e verifica. Vengono chiariti i confini tra controllo operativo, decisione organizzativa e supporto tecnico.','question','Quando una segnalazione del preposto può dirsi davvero chiusa?','case','Una protezione guasta viene segnalata via messaggio al dirigente. Il giorno seguente è ancora guasta e la squadra riprende il lavoro. Il preposto può considerare concluso il proprio compito perché ha già segnalato?','teacher_expansion',jsonb_build_array('[0–15 min] Ricostruisci un flusso di segnalazione reale.','[15–35 min] Distingui informare, segnalare, chiedere una decisione e verificare.','[35–60 min] Caso protezione guasta: responsabilità prima e dopo la segnalazione.','[60–75 min] Cooperazione con RSPP/RLS e figure decisionali.','[75–90 min] Esercizio: trasformare una segnalazione vaga in una segnalazione operativa.'),'common_errors',jsonb_build_array('Pensare che inviare un messaggio esaurisca sempre il controllo.','Segnalare senza indicare urgenza e condizione operativa.','Confondere collaborazione con trasferimento della propria funzione di vigilanza.'),'operational',jsonb_build_object('objective','Trasformare un’anomalia in presa in carico, azione e verifica.','step_by_step',jsonb_build_array('Metti in sicurezza','Descrivi il fatto','Indica il rischio','Invia al destinatario corretto','Verifica la presa in carico','Controlla il ripristino'),'stop_conditions',jsonb_build_array('Anomalia ancora presente','Nessuna presa in carico','Ripresa proposta senza ripristino o misura equivalente')),'idea_images',jsonb_build_array(jsonb_build_object('file','stop-segnala-ripristina.svg','caption','La segnalazione deve arrivare al ripristino e alla verifica.'),jsonb_build_object('file','procedura-operativa-5-fasi.svg','caption','Dal problema alla verifica finale.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:vigilanza-operativa','PR03 · Vigilanza operativa su comportamenti e condizioni',90,'Esercitare la vigilanza sull’osservanza delle disposizioni e delle procedure di sicurezza.',jsonb_build_object('didactic_version','preposto-v2','code','PR03','minutes',90,'slide_title','Vigilare significa osservare ciò che accade davvero','summary','La vigilanza del preposto non è presenza passiva: richiede osservazione delle condizioni, confronto con le direttive, correzione tempestiva e controllo che la deviazione non si ripeta.','detail','L’unità usa osservazioni guidate di scene di lavoro per distinguere comportamento sicuro, deviazione occasionale, prassi tollerata e condizione tecnica non sicura. Si lavora sul controllo dell’osservanza dell’art. 19 e delle disposizioni aziendali applicabili.','question','Quali segnali ti fanno capire che una deviazione sta diventando una prassi normale nel gruppo?','case','Un lavoratore non usa una protezione perché rallenta il compito. Il preposto lo richiama; dieci minuti dopo il comportamento si ripete. Qual è il passo successivo?','teacher_expansion',jsonb_build_array('[0–15 min] Osservazione di una scena: cosa controllerebbe un preposto?','[15–35 min] Vigilanza su comportamenti, condizioni e misure.','[35–55 min] Deviazione occasionale vs prassi tollerata.','[55–75 min] Caso protezione non usata: dal richiamo al controllo dell’effettivo adeguamento.','[75–90 min] Checklist di vigilanza adattata alla mansione.'),'common_errors',jsonb_build_array('Ridurre la vigilanza a richiamare verbalmente.','Controllare solo i lavoratori e non le condizioni operative.','Tollerare deviazioni ripetute perché il lavoro deve proseguire.'),'operational',jsonb_build_object('objective','Osservare, confrontare con la regola, correggere e verificare.','step_by_step',jsonb_build_array('Osserva','Confronta con direttive/procedure','Intervieni','Spiega il motivo','Verifica l’adeguamento','Escala se la deviazione persiste'),'stop_conditions',jsonb_build_array('Comportamento con pericolo immediato','Protezione essenziale bypassata','Deviazione reiterata non corretta')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-inspection-flow.svg','caption','Ciclo di vigilanza: osserva, correggi, verifica.'),jsonb_build_object('file','scene-generale.svg','caption','Scenario per esercitare l’osservazione operativa.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:interruzione-segnalazione','PR04 · Intervento, interruzione dell’attività e segnalazione',90,'Saper intervenire e interrompere l’attività quando le condizioni di sicurezza lo richiedono.',jsonb_build_object('didactic_version','preposto-v2','code','PR04','minutes',90,'slide_title','Quando il preposto deve dire STOP','summary','Il preposto deve sapere quando una correzione è sufficiente e quando invece occorre interrompere l’attività, mettere in sicurezza e segnalare la situazione.','detail','La didattica è centrata su soglie decisionali: pericolo grave o immediato, mancata attuazione delle disposizioni, persistenza della deviazione, cambiamento non previsto, misura di sicurezza assente o inefficace.','question','Qual è la differenza tra richiamare un lavoratore e interrompere una lavorazione?','case','Durante un’attività manca una protezione prevista. Il responsabile di produzione chiede di proseguire per venti minuti in attesa del ricambio. Come deve procedere il preposto?','teacher_expansion',jsonb_build_array('[0–15 min] Tre scenari: continua, correggi, stop. La classe deve scegliere rapidamente.','[15–35 min] Funzioni di interruzione, informazione e segnalazione.','[35–55 min] Condizioni che cambiano durante l’attività.','[55–75 min] Caso protezione assente e pressione produttiva.','[75–90 min] Debrief: come comunicare uno stop senza trasformarlo in conflitto personale.'),'common_errors',jsonb_build_array('Aspettare un’autorizzazione quando la situazione richiede un intervento immediato.','Confondere urgenza produttiva con accettabilità del rischio.','Interrompere senza poi attivare ripristino e segnalazione.'),'operational',jsonb_build_object('objective','Decidere se continuare, correggere o interrompere.','step_by_step',jsonb_build_array('Riconosci la deviazione','Valuta l’immediatezza del rischio','Intervieni','Interrompi se necessario','Metti in sicurezza','Segnala','Riprendi solo dopo verifica'),'stop_conditions',jsonb_build_array('Pericolo grave/immediato','Misura essenziale assente','Ordine operativo incompatibile con sicurezza','Condizione nuova non controllata')),'idea_images',jsonb_build_array(jsonb_build_object('file','stop-segnala-ripristina.svg','caption','STOP, segnalazione, ripristino e verifica.'),jsonb_build_object('file','modello-farfalla-rischio.svg','caption','Dove interrompere la catena prima dell’evento.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:valutazione-situazioni-rischio','PR05 · Valutare situazioni di rischio nel contesto operativo',90,'Riconoscere rischi e cambiamenti nel contesto in cui opera il preposto e collegarli alle misure previste.',jsonb_build_object('didactic_version','preposto-v2','code','PR05','minutes',90,'slide_title','Il rischio cambia quando cambia il lavoro','summary','Il preposto non redige il DVR, ma deve saper riconoscere quando persone, ambiente, attrezzature o modalità operative non corrispondono più alle condizioni previste e richiedono un intervento.','detail','L’unità collega valutazione dei rischi aziendale, misure tecniche/organizzative/procedurali e osservazione sul campo. Include rischi interferenziali, appalti, somministrazione e subappalti quando pertinenti al contesto.','question','Quali cambiamenti apparentemente piccoli possono rendere non più adeguata una procedura già conosciuta?','case','Una squadra esterna entra nell’area per una manutenzione urgente e occupa un passaggio normalmente usato dai lavoratori interni. La procedura ordinaria può continuare invariata?','teacher_expansion',jsonb_build_array('[0–15 min] Elenca cambiamenti che modificano il rischio: persone, spazio, sequenza, mezzi, sostanze, tempi.','[15–35 min] DVR e misure: cosa deve sapere operativamente il preposto.','[35–55 min] Rischi interferenziali e presenza di imprese esterne.','[55–75 min] Caso manutenzione urgente: leggere il nuovo scenario.','[75–90 min] Esercizio: cosa è cambiato? quale misura non è più sufficiente? chi coinvolgere?'),'common_errors',jsonb_build_array('Pensare che una procedura sia valida indipendentemente dal contesto.','Trattare impresa esterna e squadra interna come attività separate anche quando interferiscono.','Pretendere dal preposto una valutazione tecnica che richiede altre funzioni invece di chiedergli riconoscimento e segnalazione.'),'operational',jsonb_build_object('objective','Riconoscere variazioni che possono modificare il rischio e attivare il riesame operativo.','step_by_step',jsonb_build_array('Confronta scenario reale con quello previsto','Individua cosa è cambiato','Verifica misure applicabili','Gestisci interferenze immediate','Coinvolgi figure competenti','Aggiorna modalità operative prima di riprendere'),'stop_conditions',jsonb_build_array('Interferenza non gestita','Procedura non applicabile','Nuovo rischio non controllato')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-dvr-reading.svg','caption','Dal DVR alla situazione reale di lavoro.'),jsonb_build_object('file','idea-duvri.svg','caption','Interferenze: attività che si incontrano nello stesso contesto.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:controllo-misure-esecuzione','PR06 · Controllare misure, procedure e corretta esecuzione',90,'Verificare che direttive, misure di prevenzione/protezione e modalità operative siano realmente applicate.',jsonb_build_object('didactic_version','preposto-v2','code','PR06','minutes',90,'slide_title','Una misura esiste solo se funziona nel lavoro reale','summary','Il controllo del preposto deve collegare regola e realtà: protezioni disponibili, procedure applicabili, DPI idonei e usati, attrezzature nelle condizioni previste, area organizzata e lavoratori in grado di operare correttamente.','detail','Il focus è il controllo della corretta esecuzione: non basta verificare la presenza formale di una misura, bisogna osservare se è effettivamente utilizzabile, compresa e mantenuta durante il lavoro.','question','Che differenza c’è tra verificare che un DPI sia stato consegnato e verificare che la misura sia efficace?','case','Tutti hanno il DPI previsto, ma due lavoratori lo indossano in modo incompatibile con la protezione richiesta. Il registro di consegna è firmato. Il controllo è superato?','teacher_expansion',jsonb_build_array('[0–15 min] Presenza della misura vs efficacia reale.','[15–35 min] Controllo di procedure, DPI, protezioni e attrezzature.','[35–55 min] Come verificare senza trasformare la vigilanza in burocrazia.','[55–75 min] Caso DPI consegnato ma usato male.','[75–90 min] Costruzione di una checklist minima: cosa vedo, cosa chiedo, cosa provo, cosa registro.'),'common_errors',jsonb_build_array('Equivalere documento firmato a misura efficace.','Controllare solo all’inizio e non durante l’attività.','Correggere l’uso senza capire se addestramento, scelta o organizzazione sono inadeguati.'),'operational',jsonb_build_object('objective','Verificare l’efficacia reale delle misure durante l’esecuzione.','step_by_step',jsonb_build_array('Verifica disponibilità','Verifica idoneità','Osserva l’uso','Correggi','Controlla di nuovo','Segnala cause strutturali'),'stop_conditions',jsonb_build_array('DPI necessario assente/non idoneo','Protezione tecnica inefficace','Attrezzatura fuori condizioni previste','Procedura non eseguibile in sicurezza')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-dpi-hierarchy.svg','caption','Il DPI è parte di un sistema di misure.'),jsonb_build_object('file','procedura-operativa-5-fasi.svg','caption','Preparazione, esecuzione e verifica devono restare coerenti.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:comunicazione-feedback','PR07 · Comunicazione, correzione e feedback',90,'Comunicare efficacemente con i lavoratori e con le altre figure della prevenzione, anche in presenza di resistenze.',jsonb_build_object('didactic_version','preposto-v2','code','PR07','minutes',90,'slide_title','Correggere un comportamento senza perdere il controllo della situazione','summary','La comunicazione del preposto deve essere chiara, tempestiva e verificabile: dire cosa non va, quale comportamento è atteso, perché è necessario e controllare che l’indicazione sia stata compresa e applicata.','detail','Si lavora su comunicazione e sensibilizzazione, con attenzione a neoassunti, somministrati, lavoratori stranieri e situazioni in cui lingua, esperienza o pressione del gruppo possono ridurre la comprensione.','question','Come capisci se una disposizione è stata davvero compresa e non soltanto ascoltata?','case','Un neoassunto annuisce alle istruzioni ma durante il compito imita una scorciatoia usata dagli altri. Come intervieni senza limitarti a ripetere la regola?','teacher_expansion',jsonb_build_array('[0–15 min] Trasforma tre ordini generici in indicazioni osservabili.','[15–35 min] Comunicazione breve: fatto, rischio, comportamento atteso, verifica.','[35–55 min] Neoassunti, somministrati, lavoratori stranieri: controllare comprensione e integrazione nel gruppo.','[55–75 min] Caso della scorciatoia imitata.','[75–90 min] Role play: correzione rispettosa ma ferma e verifica del feedback.'),'common_errors',jsonb_build_array('Confondere tono autoritario con chiarezza.','Chiedere solo “hai capito?”.','Correggere il singolo ignorando una prassi sbagliata condivisa dal gruppo.'),'operational',jsonb_build_object('objective','Dare indicazioni chiare, verificare comprensione e ottenere un comportamento osservabile.','step_by_step',jsonb_build_array('Descrivi il fatto','Spiega il rischio','Indica cosa fare','Fai riformulare/dimostrare','Osserva l’esecuzione','Dai feedback'),'stop_conditions',jsonb_build_array('Istruzione non compresa','Barriera linguistica non gestita','Lavoratore non addestrato per l’attività')),'idea_images',jsonb_build_array(jsonb_build_object('file','idea-safety-system.svg','caption','La comunicazione collega persone e misure.'),jsonb_build_object('file','stop-segnala-ripristina.svg','caption','Messaggi chiari nei momenti critici.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false))),
    ('preposto:scenari-decisionali','PR08 · Scenari integrati e decisioni del preposto',90,'Integrare ruolo, vigilanza, valutazione operativa e comunicazione in scenari realistici.',jsonb_build_object('didactic_version','preposto-v2','code','PR08','minutes',90,'slide_title','Sei il preposto: cosa fai adesso?','summary','L’ultima unità non aggiunge una nuova lista di nozioni: obbliga a prendere decisioni motivate davanti a situazioni ambigue, pressioni produttive, interferenze, anomalie e quasi incidenti.','detail','Gli scenari devono essere adattati al DVR e alle mansioni reali. Ogni decisione viene valutata su quattro domande: cosa osservi, cosa fai subito, chi coinvolgi, quando permetti la ripresa.','question','Quali informazioni minime ti servono per decidere se correggere, interrompere o chiedere un intervento organizzativo?','case','A fine turno una lavorazione è in ritardo; un riparo è stato temporaneamente rimosso, entra una squadra esterna per manutenzione e un lavoratore riferisce un quasi incidente avvenuto poco prima. Il responsabile chiede di chiudere comunque il lavoro. Ordina le prime cinque azioni del preposto.','teacher_expansion',jsonb_build_array('[0–10 min] Spiega il metodo decisionale: osserva → priorità → azione → comunicazione → verifica.','[10–30 min] Scenario 1: comportamento non conforme reiterato.','[30–50 min] Scenario 2: interferenza/appalto e area modificata.','[50–70 min] Scenario 3: near miss e pressione produttiva.','[70–85 min] Scenario integrato a gruppi: decisione motivata e confronto.','[85–90 min] Chiusura: cinque domande che un preposto deve farsi prima di far proseguire il lavoro.'),'common_errors',jsonb_build_array('Cercare una risposta unica senza leggere il contesto.','Pensare prima alla colpa e poi alla messa in sicurezza.','Riprendere l’attività senza criterio esplicito di verifica.'),'operational',jsonb_build_object('objective','Prendere una decisione operativa motivata e tracciabile.','step_by_step',jsonb_build_array('Osserva i fatti','Dai priorità ai pericoli immediati','Intervieni/stop','Comunica e coinvolgi','Definisci condizioni di ripresa','Verifica'),'stop_conditions',jsonb_build_array('Più criticità simultanee non controllate','Near miss con causa ancora presente','Interferenza non coordinata','Pressione produttiva che richiede bypass di misure')),'idea_images',jsonb_build_array(jsonb_build_object('file','modello-farfalla-rischio.svg','caption','Cause, barriere, evento e conseguenze come guida al debrief.'),jsonb_build_object('file','piramide-pericoli.svg','caption','Incidenti mancati e anomalie come segnali da usare.')),'quality',jsonb_build_object('score',100,'complete',true,'classroom_first',true,'final_assessment',false,'scenario_based',true)))
  ) x(stable_key,title,minutes,summary,content)
  loop
    insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    values(r.stable_key,r.title,r.summary,r.minutes,'preposto',array['preposto','asr-2025','role-specific'],true,jsonb_build_object('didactic_version','preposto-v2','competency_level','preposto','regulatory_basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR'))
    on conflict (stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=public.learning_units.metadata||excluded.metadata,updated_at=now()
    returning id into v_lu_id;
    insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    values(v_lu_id,1,'published',r.content,now())
    on conflict (learning_unit_id,version_number) do update set status='published',content=excluded.content,published_at=coalesce(public.learning_unit_versions.published_at,now());
  end loop;

  select id into v_course_id from public.courses where stable_key='preposto';
  if v_course_id is not null then
    update public.courses set metadata=metadata||jsonb_build_object('didactic_preview_version','preposto-v2','didactic_macro_blocks',4,'didactic_atomic_units',8,'didactic_focus','decision_vigilance_and_deviation_management','final_test_builder_paused',true,'delivery_constraint','synchronous_or_classroom','asynchronous_elearning_allowed',false,'prerequisite_training','worker_general_and_specific'),updated_at=now() where id=v_course_id;
    insert into public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot)
    values(v_course_id,2,'draft',jsonb_build_object('didactic_version','preposto-v2','macro_blocks',jsonb_build_array(jsonb_build_object('key','pr-a','title','Ruolo, obblighi e relazioni del preposto','minutes',180),jsonb_build_object('key','pr-b','title','Vigilare, intervenire, interrompere','minutes',180),jsonb_build_object('key','pr-c','title','Valutare situazioni di rischio e controllare il lavoro','minutes',180),jsonb_build_object('key','pr-d','title','Comunicare e decidere nei casi reali','minutes',180)),'atomic_learning_units',8,'total_minutes',720,'internal_didactic_allocation',true,'statutory_per_module_duration',false,'purpose','classroom_and_teacher_support','final_assessment_in_scope',false),jsonb_build_object('basis','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR; art. 19 e art. 37 d.lgs. 81/2008','minimum_minutes',720,'prerequisite','formazione generale e specifica lavoratori','delivery',jsonb_build_object('classroom',true,'vcs',true,'elearning_asynchronous',false)))
    on conflict (course_id,version_number) do update set status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot returning id into v_course_version_id;
    delete from public.course_module_units where module_id in (select id from public.course_modules where course_version_id=v_course_version_id);
    delete from public.course_modules where course_version_id=v_course_version_id;
    insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_course_version_id,'pr-a','PR-A · Ruolo, obblighi e relazioni del preposto',0,180) returning id into v_module_id;
    insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) select v_module_id,luv.id,x.pos,true,0,true,jsonb_build_object('didactic_version','preposto-v2','delivery','synchronous_or_classroom') from (values ('preposto:ruolo-obblighi-relazioni',1),('preposto:rapporti-cooperazione',2)) x(key,pos) join public.learning_units lu on lu.stable_key=x.key join public.learning_unit_versions luv on luv.learning_unit_id=lu.id and luv.version_number=1;
